'use strict';
const express=require('express'),fs=require('fs'),path=require('path'),crypto=require('crypto');
const {db}=require('../db'),{DATA_DIR,APP_DIR}=require('../paths'),{createBridge}=require('../flowBridge.cjs');
const profile=require('../flowProfile.cjs').createFlowProfile({directory:DATA_DIR});
const bridge=createBridge({directory:DATA_DIR}),router=express.Router();let active=null;
const profileBridge=require('../flowProfileBridge.cjs').bindProfile(profile,bridge,APP_DIR,DATA_DIR);
const local=req=>['127.0.0.1','::1','::ffff:127.0.0.1'].includes(req.socket.remoteAddress);
const originOK=req=>!req.get('origin')||/^http:\/\/(localhost|127\.0\.0\.1):3001$/.test(req.get('origin'));
const wrap=fn=>async(req,res)=>{try{await fn(req,res)}catch(e){res.status(e.status||400).json({error:e.message})}};
router.use((req,res,next)=>{res.set('Cache-Control','no-store');if(!local(req))return res.sendStatus(403);next()});
router.use('/bridge',(req,res,next)=>{const origin=req.get('origin');if(origin&&!/^chrome-extension:\/\/[a-p]{32}$/.test(origin))return res.sendStatus(403);if(origin){res.set('Access-Control-Allow-Origin',origin);res.set('Vary','Origin');res.set('Access-Control-Allow-Headers','Authorization,Content-Type');res.set('Access-Control-Allow-Methods','POST,OPTIONS')}if(req.method==='OPTIONS')return res.sendStatus(204);if(!bridge.authenticate(req.get('authorization')))return res.status(403).json({error:'Mã ghép nối không đúng.'});next()});
router.post('/bridge/tick',wrap(async(req,res)=>{bridge.heartbeat(req.body);res.json({command:bridge.next(req.body.channel)})}));
router.post('/bridge/result',wrap(async(req,res)=>res.json({accepted:bridge.result(req.body,req.body.channel)})));
router.use((req,res,next)=>{if(req.path==='/pairing'&&/^chrome-extension:\/\/[a-p]{32}$/.test(req.get('origin')||'')){res.set('Access-Control-Allow-Origin',req.get('origin'));return next()}return originOK(req)?next():res.sendStatus(403)});
router.post('/profile/open',wrap(async(req,res)=>{await profile.open();res.json(await profile.status())}));
router.post('/profile/connect',wrap(async(req,res)=>{await profileBridge.start();res.json(await profile.status())}));
router.get('/profile/status',wrap(async(req,res)=>res.json(await profile.status())));
router.post('/profile/close',wrap(async(req,res)=>{await profile.close();res.json({success:true})}));
router.get('/status',wrap(async(req,res)=>res.json({...bridge.status(),activeJobId:active,mode:'chrome-bridge'})));
router.post('/pairing',wrap(async(req,res)=>res.json({key:bridge.pairingKey()})));
router.post('/disconnect',wrap(async(req,res)=>{bridge.disconnect();res.json({success:true,note:'Đã ngắt cầu nối. Phiên Google trong Chrome vẫn được giữ; tác vụ đã gửi trên Google có thể tiếp tục.'})}));
router.get('/extension.zip',(_req,res)=>res.download(path.join(APP_DIR,'dist/flow-bridge.zip'),'Monday-Flow-Bridge.zip'));
const mimeExt={'image/png':'.png','image/jpeg':'.jpg','image/webp':'.webp','video/mp4':'.mp4','video/webm':'.webm'};
function localFile(url,media){if(typeof url!=='string'||url.includes('..'))throw Error('File tham chiếu không hợp lệ.');const decoded=decodeURIComponent(url);let root,file;if(/^\/(uploads|videos)\/[A-Za-z0-9_./%-]+$/.test(url)){root=fs.realpathSync(path.join(DATA_DIR,decoded.split('/')[1]));file=fs.realpathSync(path.join(DATA_DIR,decoded.slice(1)));}else if(/^\/assets\/data\/demo-refs\/[a-z0-9-]+\.(png|jpg|webp|mp4|webm)$/.test(url)){root=fs.realpathSync(path.join(APP_DIR,'dist/assets/data/demo-refs'));file=fs.realpathSync(path.join(APP_DIR,'dist',decoded.slice(1)));}else throw Error('File tham chiếu không hợp lệ.');if(!file.startsWith(root+path.sep))throw Error('File nằm ngoài thư viện.');const mime=Object.keys(mimeExt).find(k=>mimeExt[k]===path.extname(file).toLowerCase());if(!mime||!mime.startsWith(media+'/'))throw Error('Định dạng file tham chiếu chưa hỗ trợ.');if(fs.statSync(file).size>20*1024*1024)throw Error('Tham chiếu tối đa 20 MB mỗi file.');return{name:path.basename(file),mime,base64:fs.readFileSync(file).toString('base64')}}
function decodeResult(result,type){if(result?.downloadPath){if(type!=='video')throw Error('Chỉ nhập video tải từ Flow.');const home=require('os').homedir(),roots=[path.join(home,'Downloads'),path.join(home,'Desktop/AI'),path.join(DATA_DIR,'flow-downloads')].filter(p=>fs.existsSync(p)).map(p=>fs.realpathSync(p));const file=fs.realpathSync(result.downloadPath);if(!roots.some(root=>file.startsWith(root+path.sep))||path.extname(file).toLowerCase()!=='.mp4')throw Error('Video Flow phải được tải vào thư mục Downloads dạng MP4.');const bytes=fs.readFileSync(file);if(bytes.length<1000||bytes.length>100*1024*1024||bytes.toString('ascii',4,8)!=='ftyp')throw Error('MP4 tải xuống không hợp lệ.');return{bytes,ext:'.mp4'}}const m=String(result?.data||'').match(/^data:([^;,]+);base64,([A-Za-z0-9+/=]+)$/);if(!m||!mimeExt[m[1]]||!m[1].startsWith(type+'/'))throw Error('Flow chưa trả đúng loại file kết quả.');const bytes=Buffer.from(m[2],'base64');if(bytes.length<1000||bytes.length>30*1024*1024)throw Error('Dung lượng kết quả không hợp lệ.');const valid=m[1]==='image/png'?bytes.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])):m[1]==='image/jpeg'?bytes[0]===255&&bytes[1]===216&&bytes[2]===255:m[1]==='image/webp'?bytes.toString('ascii',0,4)==='RIFF'&&bytes.toString('ascii',8,12)==='WEBP':m[1]==='video/mp4'?bytes.toString('ascii',4,8)==='ftyp':bytes.toString('hex',0,4)==='1a45dfa3';if(!valid)throw Error('File kết quả không khớp định dạng.');return{bytes,ext:mimeExt[m[1]]}}
const current=id=>db.prepare('SELECT status FROM jobs WHERE id=?').get(id)?.status==='running';
async function run(id,spec){let submitted=false;try{
 const files=[...spec.refImageUrls.map(u=>localFile(u,'image')),...(spec.refVideoUrl?[localFile(spec.refVideoUrl,'video')]:[])];
 if(files.reduce((sum,f)=>sum+f.base64.length,0)>40*1024*1024)throw Error('Tổng tham chiếu quá lớn; chọn file nhỏ hơn.');
 const prepared=await bridge.request('prepare',{...spec,files,jobId:id});if(!prepared?.ready)throw Error('Flow chưa sẵn sàng.');if(!current(id))return;
 const sent=await bridge.request('generate',{jobId:id});if(!sent?.submitted)throw Error('Flow chưa xác nhận gửi tác vụ.');submitted=true;
 const deadline=Date.now()+15*60*1000;while(Date.now()<deadline&&current(id)){await new Promise(r=>setTimeout(r,2500));const state=await bridge.request('collect',{jobId:id});if(!state?.done)continue;const result=await bridge.request('download',{jobId:id,url:state.media.src}),file=decodeResult(result,spec.mediaType);if(!current(id))return;const name=id+file.ext,target=path.join(DATA_DIR,'videos',name);fs.writeFileSync(target+'.tmp',file.bytes);fs.renameSync(target+'.tmp',target);const url='/videos/'+name;db.prepare("UPDATE jobs SET status='completed',progress=100,video_url=?,thumbnail_url=?,finished_at=datetime('now'),error=NULL WHERE id=? AND status='running'").run(url,spec.mediaType==='image'?url:null,id);return;}
 if(current(id))throw Error('Flow chưa hoàn tất sau 15 phút. Kiểm tra tab Google trước khi tạo lại.');
 }catch(e){db.prepare("UPDATE jobs SET status='failed',error=?,finished_at=datetime('now') WHERE id=? AND status='running'").run(String(e.message+(submitted?' Tác vụ đã gửi tới Google; kiểm tra Flow trước khi gửi lại.':' Chưa xác nhận đã gửi tới Google.')).slice(0,1000),id)}finally{active=null}}
function inputSpec(body){
 const b=body||{},prompt=typeof b.prompt==='string'?b.prompt.trim():'';if(!prompt||prompt.length>40000)throw Error('Prompt cần có 1–40.000 ký tự.');const mediaType=b.mediaType;if(!['image','video'].includes(mediaType))throw Error('Chọn tạo ảnh hoặc video.');if(!['16:9','9:16','1:1'].includes(b.ratio))throw Error('Tỷ lệ không hợp lệ.');if(mediaType==='video'&&(!Number.isInteger(b.duration)||b.duration<3||b.duration>15))throw Error('Flow: chọn thời lượng 3–15 giây; app không tự cắt thời lượng.');const images=b.refImageUrls||[];if(!Array.isArray(images)||images.length>5)throw Error('Tối đa 5 ảnh tham chiếu.');images.forEach(u=>localFile(u,'image'));if(b.refVideoUrl)localFile(b.refVideoUrl,'video');
return{prompt,mediaType,ratio:b.ratio,duration:mediaType==='video'?b.duration:5,refImageUrls:images,refVideoUrl:b.refVideoUrl||null};
}
router.post('/check-input',wrap(async(req,res)=>{
 if(active)return res.status(409).json({error:'Flow đang xử lý một node.'});
 const state=bridge.status();if(!state.connected||!state.authenticated)throw Error('Mở dự án Flow đã đăng nhập trước.');
 const spec=inputSpec(req.body),id='check_'+crypto.randomUUID();active=id;
 try{const files=[...spec.refImageUrls.map(u=>localFile(u,'image')),...(spec.refVideoUrl?[localFile(spec.refVideoUrl,'video')]:[])];
 if(files.reduce((sum,f)=>sum+f.base64.length,0)>40*1024*1024)throw Error('Tổng tham chiếu quá lớn.');
 const result=await bridge.request('prepare',{...spec,files,jobId:id});res.json({...result,submitted:false});
 }finally{active=null}
}));
router.post('/generate',wrap(async(req,res)=>{
 if(active)return res.status(409).json({error:'Flow đang chạy một node. Đợi hoàn tất trước khi gửi node tiếp.'});const s=bridge.status();if(!s.connected||!s.authenticated)throw Error('Chưa kết nối dự án Google Flow đã đăng nhập. Mở Cài đặt → Google Flow.');
 const spec=inputSpec(req.body),{prompt,mediaType}=spec,b=req.body||{};
 const id='gf_'+crypto.randomBytes(12).toString('hex');active=id;
 try{db.prepare("INSERT INTO jobs(id,prompt,ref_tags,media_type,status,progress,duration,ratio,attempts,max_retries,timeout_minutes,sort_order,created_at,started_at) VALUES(?,?,'[]',?,'running',0,?,?,0,0,15,0,datetime('now'),datetime('now'))").run(id,prompt,mediaType,spec.duration,spec.ratio);db.exec('CREATE TABLE IF NOT EXISTS job_context(job_id TEXT PRIMARY KEY,payload TEXT NOT NULL)');db.prepare('INSERT OR REPLACE INTO job_context(job_id,payload) VALUES(?,?)').run(id,JSON.stringify({provider:'Google Flow · Chrome',mode:'canvas',graph:b.graph||null,nodeId:b.nodeId||null,prompt,ratio:b.ratio,duration:spec.duration}));}catch(e){active=null;throw e}
 res.json({job:db.prepare('SELECT * FROM jobs WHERE id=?').get(id)});setImmediate(()=>run(id,spec));
}));
router.post('/recover/:id',wrap(async(req,res)=>{if(active)throw Error('Flow đang xử lý một node.');const job=db.prepare('SELECT * FROM jobs WHERE id=?').get(req.params.id);if(!job||!job.id.startsWith('gf_')||job.media_type!=='video'||job.status!=='failed')throw Error('Chỉ nhập lại kết quả video Flow bị lỗi tải.');const url=String(req.body.url||'');if(!/^https:\/\/flow\.google\.com\/project\/[a-f0-9-]+\/edit\/[a-f0-9-]+$/.test(url))throw Error('Đường dẫn video Flow không hợp lệ.');active=job.id;try{await bridge.request('recover',{jobId:job.id,prompt:job.prompt,url});const deadline=Date.now()+120000;while(Date.now()<deadline){const state=await bridge.request('collect',{jobId:job.id});if(state?.done){const data=await bridge.request('download',{jobId:job.id,url:state.media.src}),file=decodeResult(data,'video'),name=job.id+file.ext;fs.writeFileSync(path.join(DATA_DIR,'videos',name),file.bytes);db.prepare("UPDATE jobs SET status='completed',progress=100,video_url=?,error=NULL,finished_at=datetime('now') WHERE id=?").run('/videos/'+name,job.id);return res.json({success:true,url:'/videos/'+name})}await new Promise(r=>setTimeout(r,1500))}throw Error('Chưa nhận được MP4 từ Chrome.')}finally{active=null}}));
module.exports={router,bridge,decodeResult,localFile};
